import {supportLink} from '../studio/support-link.js';
import {WORLD_ROOMS,TOKEN_ROOMS,RELAY_TARGET,roomsOf,roomLock,worldRoutes,worldGoal} from './adventure-world.js';
export function worldPanel(type,{p,s,esc,button,refs}){
 const w=s.world,r=roomsOf(p);if(!w)return null;
 if(type==='map')return {title:p.world.title,wide:true,content:`<p>Choose a discovered place to return there. Unvisited paths are named so you can plan your exploration.</p><div class="atlas-map">${WORLD_ROOMS.map(id=>`<article class="atlas-map-place ${s.room===id?'current':''}"><h3>${esc(r[id].title)}</h3><p>${s.room===id?'You are here':roomLock(s,id)||(!s.visited.includes(id)?'Not yet visited':'Discovered')}</p><small>Paths: ${worldRoutes(s)[id].map(to=>esc(r[to].title)).join(' · ')}</small>${button('Travel to '+esc(r[id].title),'map-travel',`data-room="${id}" ${s.room===id||roomLock(s,id)||!s.visited.includes(id)?'disabled':''}`)}</article>`).join('')}</div><p class="atlas-help">${s.visited.length} of 6 places discovered. ${w.tokens.length} of 3 trail tokens. Shortcuts open when you help the neighbours.</p>`};
 if(type==='quests')return {title:'Threads to follow',wide:true,content:`<p>You can follow the main story or take time for the neighbours. Side requests remain available after the ending.</p><ol class="atlas-quests">${[['main','Restore the signal',s.completed],['delivery',p.world.delivery.title,w.delivery===3],['field',p.world.field.title,w.field.solved]].map(([id,title,done])=>`<li><h3>${esc(title)}${id!=='main'?' <small>Optional</small>':''}</h3><p>${done?'Complete':esc(worldGoal(p,{...s,world:{...w,tracked:id}})||(!s.collected?`Find ${p.items.tool.name} on the woodland path.`:!s.repaired?`Bring the tool back to ${r.workshop.title}.`:`Read and connect the evidence in ${r.archive.title}.`))}</p>${button(w.tracked===id?'Following this thread':'Follow this thread','track',`data-quest="${id}" aria-pressed="${w.tracked===id}"`)}</li>`).join('')}</ol><h3>Small discoveries</h3><p>${TOKEN_ROOMS.map(id=>`${w.tokens.includes(id)?'Found':'Still to find'}: ${esc(r[id].title)}`).join(' · ')}</p>`};
 if(type==='field')return {title:p.world.field.title,content:`<p>${esc(p.world.field.prompt)}</p>${!s.inspected.includes('garden')?'<p>Read the garden clue first. Your journal keeps it for reference.</p>':`<div class="atlas-ending-choices">${p.world.field.options.map((label,i)=>button(esc(label),'field-answer',`data-index="${i}" ${w.field.solved?'disabled':''}`)).join('')}</div>`}${w.field.answer!==null?`<p>${esc(p.world.field.feedback[w.field.answer])}</p>`:''}${button(w.field.solved?'Revisit the explanation':'Read a supporting hint','field-hint')}${refs(p.world.field.sourceRefs)}${supportLink(p,'field','game-support-link')}`};
 if(type==='relay')return {title:p.world.relay.title,wide:true,content:`<p>${esc(p.world.relay.intro)}</p><p>Connect the three elbows to the engraved route. Turn a wheel clockwise to change its open sides, then test the signal. No timer, penalties or subject score.</p><div class="atlas-relay" role="group" aria-label="Three signal wheels">${w.relay.turns.map((turn,i)=>`<div><span class="atlas-pipe" aria-hidden="true" style="transform:rotate(${turn*90}deg)">┗</span>${button('Turn wheel '+(i+1),'relay-turn',`data-index="${i}" ${w.relay.solved?'disabled':''}`)}<p>Open: ${['north and east','east and south','south and west','west and north'][turn]}</p><strong>Route: ${['north and east','east and south','south and west','west and north'][RELAY_TARGET[i]]}</strong></div>`).join('')}</div>${button('Test the signal','relay-check','','atlas-primary')}${w.relay.solved?button('Choose the next thread','decision'):''}<p class="atlas-help">${w.relay.moves} wheel turns. This is a fictional mechanical puzzle, not a test of your topic knowledge.</p>${refs(p.world.relay.sourceRefs)}`};
 return null;
}
