import {newEconomy,loadEconomy,actEconomy,encodeEconomy,economySaveKey,forecastEconomy,economyAssets,economyGoals,pendingCouncil,placementIssue,tradeQuote,demandFor,economyCatalog,RETAIL,REGIONS,PRESETS,ECONOMY_MONTHS,waterTile} from './economy-engine.js';
import {economyRulesSummary} from './economy-content.js';
import {focusToken,restoreFocus,modalAccess,gameAnnouncer} from './accessibility.js';
import {supportLink} from '../studio/support-link.js';
import './economy-style.css';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const signed=n=>n>0?'+'+n:String(n);
export function mountEconomy(root,{pack,assets,storage,onExit,onLibrary,onProgress=()=>{}}){
 let {state,notice,recoveryRaw,saveBlocked=false}=loadEconomy(storage,pack),region=0,selected=14,tool='inspect',view='region',modal=null,previousFocus=null,destroyed=false;
 const expanded=pack.rulesVersion===2,{goods:GOODS,facilities:FACILITIES,technologies:TECHNOLOGIES,contracts:CONTRACTS,councilRules:COUNCIL_RULES,retailGoods}=economyCatalog(pack);
 const access=modalAccess(root),announcer=gameAnnouncer(root);
 const button=(label,act,attrs='',cls='')=>`<button type="button" data-e="${act}" ${attrs} class="${cls}">${label}</button>`;
 const art=kind=>assets.expansion?.town?.[kind]||assets.expansion?.town?.[FACILITIES[kind]?.art||kind]||assets.town?.buildings?.[FACILITIES[kind]?.art||kind];
 const picture=(kind,cls='')=>art(kind)?`<img class="${cls}" src="${esc(art(kind).url)}" alt="">`:'';
 const ended=()=>state.status!=='playing';
 const locked=()=>ended()||pendingCouncil(state)>=0;
 const disabled=condition=>condition?'disabled':'';
 const label=i=>`Tile ${i%6+1}, ${Math.floor(i/6)+1}: ${state.boards[region]?.[i]?.kind==='hall'?'District hall':FACILITIES[state.boards[region]?.[i]?.kind]?.name||(waterTile(i)?'River':'Open land')}`;
 const sources=ids=>ids.map(id=>pack.sources.find(s=>s.id===id)).filter(Boolean).map(s=>`<blockquote>${esc(s.excerpt)}<footer>${esc(s.title)}<br>${esc(s.locator)}</footer></blockquote>`).join('');
 function modalHTML(){const host=root.querySelector('.e-modal-host');if(!modal){host.innerHTML='';access.sync(null);return;}host.innerHTML=`<div class="e-scrim"><section class="e-dialog" role="dialog" aria-modal="true" aria-labelledby="e-dialog-title"><header><h2 tabindex="-1" id="e-dialog-title">${esc(modal.title)}</h2>${button('Close','close')}</header>${modal.html}</section></div>`;access.sync(host.querySelector('.e-dialog'));}
 function open(title,html){modal={title,html};modalHTML();root.querySelector('#e-dialog-title').focus();}
 function close(){modal=null;modalHTML();restoreFocus(root,previousFocus);}
 function goals(){return `<ul class="e-goals">${economyGoals(pack,state).map(g=>`<li><span>${esc(g.label)}</span><b>${g.value} / ${g.target}</b><progress max="${g.target}" value="${Math.max(0,g.value)}" aria-label="${esc(g.label)}"></progress></li>`).join('')}</ul>`;}
 function map(f){
  const anchor=i=>({x:330+(i%6-Math.floor(i/6))*43,y:62+(i%6+Math.floor(i/6))*22});
  const board=state.boards[region];
  if(!board)return `<section class="e-locked-region">${picture(region===1?'workshop':'market')}<h2>${esc(pack.regions[region].name)}</h2><p>${esc(pack.regions[region].description)}</p><p>Route opens after month ${REGIONS[region].opens}. Connection costs ${REGIONS[region].cost}. Districts connect in order.</p>${button('Connect district','expand',`data-region="${region}" ${disabled(locked()||state.month<REGIONS[region].opens||!state.boards[region-1]||state.funds<REGIONS[region].cost)}`,'e-primary')}</section>`;
  const tiles=board.map((b,i)=>{const p=anchor(i);return `<g role="button" tabindex="${i===selected?0:-1}" data-e-tile="${i}" aria-label="${esc(label(i))}" aria-pressed="${i===selected}" class="e-tile ${selected===i?'selected':''}"><path d="M${p.x} ${p.y-22}l43 22 -43 22 -43 -22Z" fill="${waterTile(i)?'#68999c':b?.kind==='road'?'#c4b690':(i+Math.floor(i/6))%2?'#9da87c':'#a8b187'}"/><path class="e-tile-edge" d="M${p.x} ${p.y-22}l43 22 -43 22 -43 -22Z"/></g>`;}).join('');
  const buildings=board.map((b,i)=>({b,i})).filter(x=>x.b&&x.b.kind!=='road').sort((a,b)=>{const p=anchor(a.i),q=anchor(b.i);return p.y-q.y||p.x-q.x;}).map(({b,i})=>{const p=anchor(i),image=art(b.kind),offline=!f.connected[region].has(i)||!b.enabled;return `<g aria-hidden="true" pointer-events="none" opacity="${offline?'.5':'1'}">${image?`<image href="${esc(image.url)}" x="${p.x-54}" y="${p.y-86}" width="108" height="108"/>`:''}${offline?`<circle cx="${p.x}" cy="${p.y+4}" r="5" fill="#a34835"/>`:''}</g>`;}).join('');
  const badges=expanded?board.map((b,i)=>{const name={sheep:'Wool',weavery:'Cloth',tailor:'Clothing',furnitureworks:'Furniture'}[b?.kind];if(!name)return '';const p=anchor(i),width=name.length*6+10;return `<g aria-hidden="true" pointer-events="none"><rect x="${p.x-width/2}" y="${p.y+3}" width="${width}" height="17" rx="2" fill="#203845"/><text class="e-industry-badge" x="${p.x}" y="${p.y+15}" text-anchor="middle" fill="#f2ead7" font-size="11">${name}</text></g>`;}).join(''):'';
  return `<div class="e-map" style="background-image:url('${esc(assets.town?.backdrop||'')}')"><svg viewBox="0 0 660 350" aria-label="${esc(pack.regions[region].name)} district board. Arrow keys move between tiles; Enter selects.">${tiles}${buildings}${badges}</svg></div><details class="e-tile-list"><summary>Choose a tile from a list</summary><label for="e-tile-choice">Tile</label><select id="e-tile-choice">${board.map((b,i)=>`<option value="${i}" ${i===selected?'selected':''}>${esc(label(i))}</option>`).join('')}</select>${button('Select tile','choose-tile')}</details>`;
 }
 function inspector(f){const b=state.boards[region]?.[selected],spec=FACILITIES[b?.kind],op=f.operations.find(x=>x.region===region&&x.index===selected);return `<section class="e-inspector"><span>${esc(label(selected).split(':')[0])}</span><h2>${esc(b?.kind==='hall'?'District hall':spec?.name||'Open land')}</h2>${b?picture(b.kind,'e-building-art'):''}${b?`<p>${f.connected[region].has(selected)?'Connected to the road network.':'Disconnected: upkeep still applies.'}</p>${spec?`<p>Monthly upkeep ${spec.upkeep}.${spec.workers?` A shift needs ${spec.workers} workers.`:''}</p>`:''}${op?`<p><strong>${op.amount} ${esc(GOODS[op.output].name.toLowerCase())} next month.</strong> ${esc(op.reason)}.</p>`:''}${spec?.output?`<p>Inputs per unit: ${Object.entries(spec.inputs).map(([k,v])=>v+' '+GOODS[k].name).join(', ')||'one cash for raw materials'}. Output before wage/research changes: ${spec.quantity}.</p>${button(b.enabled?'Pause shifts':'Resume shifts','operate',disabled(locked()))}`:''}${spec?button('Remove · refund '+Math.floor(spec.cost/2),'remove',disabled(locked()),'e-subtle'):''}`:`<p>${waterTile(selected)?'The river remains clear. Roads cross at the existing bridge.':'Choose a building, then select this tile. Roads must connect to the district hall.'}</p>`}</section>`;}
 function buildPalette(){return `<section class="e-build"><h2>Build the district</h2><div class="e-palette">${button('Inspect','tool','data-kind="inspect" aria-pressed="'+(tool==='inspect')+'"',tool==='inspect'?'selected':'')}${Object.entries(FACILITIES).map(([k,f])=>button(`${picture(k)}<span>${esc(f.name)}<small>${f.cost} cash</small></span>`,'tool',`data-kind="${k}" aria-pressed="${tool===k}" ${disabled(locked())}`,tool===k?'selected':'')).join('')}</div></section>`;}
 function contracts(){return `<section class="e-contracts"><h2>Contracts on the quay</h2>${CONTRACTS.filter(c=>state.month>=c.start&&(!state.contracts.includes(c.id)&&state.month<c.deadline||state.contracts.includes(c.id))).slice(-3).map(c=>`<article><div><h3>${esc(c.name)}</h3><p>${c.quantity} ${GOODS[c.good].name.toLowerCase()} · payment ${c.reward} · before month ${c.deadline}</p></div>${state.contracts.includes(c.id)?'<strong>Delivered</strong>':button('Deliver contract','contract',`data-id="${c.id}" ${disabled(locked()||state.stock[c.good]<c.quantity)}`)}</article>`).join('')||'<p>The next contract appears after the current four-month period.</p>'}<p class="e-muted">Reserve retail stock or buy the required goods. Local contract deliveries do not use the quay transport allowance. Missed deadlines close the contract without a fine.</p></section>`;}
 function forecast(f){return `<section class="e-forecast"><h2>Next month</h2><dl>${[['Retail sales',f.sales],['Household tax',f.taxes],['Wages',-f.wages],['Upkeep',-f.upkeep],['Raw material inputs',-f.materials],['Interest',-f.interest],...(expanded?[['Quality finishing',-f.qualityCosts]]:[]),['Public spending',-state.services]].filter(([k])=>k!=='Household tax'||pack.preset==='regional').map(([k,v])=>`<div><dt>${k}</dt><dd>${signed(v)}</dd></div>`).join('')}<div class="e-total"><dt>Operating balance</dt><dd>${signed(f.net)}</dd></div></dl><p>${f.workersUsed} / ${f.people} workers allocated. Nature ${signed(f.natureDelta)}.</p>${f.shock?`<p class="e-shock"><b>${f.shock.title}.</b> ${f.shock.text}</p>`:''}<p class="e-muted">Forecast uses the current plan. Construction, trades, loans and contracts appear separately in the cash ledger.</p>${button('Inspect the ledger','view','data-view="ledger"','e-subtle')}</section>`;}
 function council(){const i=pendingCouncil(state);if(i<0)return '';const e=pack.events[i];return `<section class="e-council"><span>Council meeting · month ${state.month}</span><h2 id="e-council-title" tabindex="-1">${esc(e.title)}</h2><p>${esc(e.prompt)}</p><div class="e-choices">${e.choices.map((c,j)=>button(`${esc(c.label)}<small>${esc(COUNCIL_RULES[i][j].label)}</small>`,'decision',`data-choice="${j}" ${disabled(state.funds<COUNCIL_RULES[i][j].cost)}`)).join('')}</div>${button('Read decision evidence','event-evidence',`data-event="${i}"`)}${supportLink(pack,`council-${i}`,'e-help','Work through the trade-off')}</section>`;}
 function company(f){return `<div class="e-commerce"><section><h2>Your market stall</h2><p>${expanded?'Customers choose among your company and two competing firms. Compare projected sales in The competition; prices and quality are authored game assumptions.':'The rival changes prices on a fixed monthly cycle. Higher prices can reduce demand; demand is an authored game rule.'}</p><div class="e-product-lines">${retailGoods.map(g=>`<article><h3>${GOODS[g].name}</h3><p>${state.stock[g]} in store · ${expanded?'projected retail sales':'rival price '+state.rival[g]+' · next-month demand'} ${expanded?f.sold[g]:demandFor(state,g)}</p><label for="e-price-${g}">${GOODS[g].name} selling price</label><select id="e-price-${g}" data-price="${g}" ${disabled(locked())}>${Array.from({length:RETAIL[g].max-RETAIL[g].min+1},(_,i)=>i+RETAIL[g].min).map(n=>`<option ${state.prices[g]===n?'selected':''}>${n}</option>`).join('')}</select>${button(state.selling[g]?'Reserve stock instead':'Resume retail sales','selling',`data-good="${g}" ${disabled(locked())}`)}<small>${state.selling[g]?'Retail is enabled.':'Stock is reserved for contracts or trade.'}</small>${expanded?`<p>Quality ${state.quality[g]} / 2 · finishing cost ${state.quality[g]} per unit sold.</p>${button(state.quality[g]===2?'Quality fully developed':'Improve quality · '+35*(state.quality[g]+1)+' cash','quality',`data-good="${g}" aria-label="Improve ${GOODS[g].name.toLowerCase()} quality for ${35*(state.quality[g]+1)} cash" ${disabled(locked()||state.quality[g]===2||state.funds<35*(state.quality[g]+1))}`)}`:''}</article>`).join('')}</div>${button('Fund marketing · 10 cash','marketing',disabled(locked()||state.marketing||state.funds<10))}<p>${expanded?'One-month market appeal bonus: +8 in every retail sector. It changes relative appeal, not the number of customers.':'One-month demand bonus: +4 for both products.'} Compare it with spare production and shop capacity.</p></section><section><h2>The trading quay</h2><p>Buy inputs or sell surplus at the displayed quotes. Transport remaining: ${tradeQuote(state,'grain').capacity-state.tradeUsed} units.</p><div class="e-table-wrap"><table><caption>Quay trades · purchases and sales share the transport allowance</caption><thead><tr><th>Good</th><th>Stock</th><th>Buy one</th><th>Sell one</th></tr></thead><tbody>${Object.entries(GOODS).map(([g,item])=>{const q=tradeQuote(state,g);return `<tr><th>${item.name}</th><td>${state.stock[g]} / ${economyAssets(state).capacity}</td><td>${button(String(q.buy),'trade',`data-good="${g}" data-side="buy" aria-label="Buy one ${g} for ${q.buy}" ${disabled(locked()||state.tradeUsed>=q.capacity||state.funds<q.buy||state.stock[g]>=economyAssets(state).capacity)}`)}</td><td>${button(String(q.sell),'trade',`data-good="${g}" data-side="sell" aria-label="Sell one ${g} for ${q.sell}" ${disabled(locked()||state.tradeUsed>=q.capacity||!state.stock[g])}`)}</td></tr>`;}).join('')}</tbody></table></div></section>${contracts()}</div>`;}

 function competition(){const f=forecastEconomy(state),last=state.marketHistory.at(-1);return `<section class="e-competition"><header><h2>The trading exchange</h2><p>Meridian Trading pursues volume; Bramble & Co. invests in quality. Both pay for stock and upgrades. Their next prices respond to public sales, never your learning profile.</p></header><div class="e-rivals">${state.rivals.map(r=>{const h=r.history.at(-1);return `<article class="e-rival e-rival-${r.id}"><h3>${esc(r.name)}</h3><p>${esc(r.strategy)} · quality ${r.quality} / 2</p><dl><div><dt>Treasury</dt><dd>${r.funds}</dd></div><div><dt>Last sales</dt><dd>${h?.revenue??'—'}</dd></div><div><dt>Last investment</dt><dd>${h?.investment??'—'}</dd></div></dl><p class="e-rival-decision">${esc(r.decision)}</p><div class="e-table-wrap"><table><caption>Posted prices and monthly capacity</caption><thead><tr><th>Product</th><th>Price</th><th>Capacity</th><th>Stored</th></tr></thead><tbody>${retailGoods.map(g=>`<tr><th>${GOODS[g].name}</th><td>${r.prices[g]}</td><td>${r.capacity[g]}</td><td>${r.stock[g]}</td></tr>`).join('')}</tbody></table></div>${h?`<p class="e-muted">Last month: ${h.opening} opening cash + ${h.revenue} revenue − ${h.production} production − ${h.upkeep} upkeep − ${h.investment} investment = ${h.closing}.</p>`:''}</article>`;}).join('')}</div><h2>${ended()?'Final market results':'Next month’s customers'}</h2><p>${ended()?'Actual sales from month '+last.month+'.':'Forecast at currently posted prices, stock, production and quality. Changing a plan changes this forecast; rivals adjust their next prices after the month ends.'}</p><div class="e-market-sectors">${retailGoods.map(g=>{const m=(ended()?last.goods:f.market)[g];return `<article><h3>${GOODS[g].name}</h3><p>${m.buyers} customers · ${m.unserved} unserved</p><div class="e-share-bar" aria-hidden="true">${m.offers.map((o,i)=>`<span class="e-share-${i}" style="width:${m.buyers?o.sold/m.buyers*100:0}%"></span>`).join('')}</div><ul>${m.offers.map(o=>`<li><span>${esc(o.name)}</span><b>${o.sold} sales · ${m.buyers?Math.round(o.sold/m.buyers*100):0}% of customers</b></li>`).join('')}</ul></article>`;}).join('')}</div><details class="e-rival-record"><summary>How competitors make decisions</summary><p>Customers favour lower prices, quality and promotion, up to each seller’s available stock and shop capacity. Orders not filled can go to another supplier. Prices move by at most one per month: weak sales trigger a cut; a sell-out below your price can trigger a rise. Every third month a rival with at least 190 cash can buy an 80-cash capacity upgrade; Bramble first buys an 85-cash quality upgrade. They must pay production and upkeep. The published arithmetic is an authored game model, not evidence of real market behaviour.</p></details>${button('Adjust your market plan','view','data-view="market"')}</section>`;}
 function industries(){const f=forecastEconomy(state),chains=[['Food','farm','mill','bakery'],['Tools','forestry','mine','toolworks'],['Textiles','sheep','weavery','tailor'],['Upholstery','furnitureworks']];return `<section class="e-industries"><h2>From raw materials to a finished product</h2><p>New campaigns need at least four units manufactured in three retail sectors. Buying and reselling goods does not establish an industry. Production uses the shared workforce and inventory across connected districts.</p>${chains.map(([name,...kinds])=>`<article class="e-chain"><h3>${name}</h3><div class="e-chain-steps">${kinds.map(k=>{const b=FACILITIES[k],made=f.operations.filter(o=>o.kind===k).reduce((n,o)=>n+o.amount,0),total=state.history.reduce((n,h)=>n+h.made[b.output],0);return `<section>${picture(k)}<h4>${b.name}</h4><p>${Object.entries(b.inputs).map(([g,n])=>`${n} ${GOODS[g].name.toLowerCase()}`).join(' + ')||'1 cash for each raw unit'} → 1 ${GOODS[b.output].name.toLowerCase()}</p><p>Base shift: ${b.quantity} units · ${b.workers} workers · upkeep ${b.upkeep}.</p><p>${made} projected next month · ${total} manufactured so far.</p>${b.tech&&!state.tech.includes(b.tech)?`<p class="e-shock">Requires ${TECHNOLOGIES[b.tech].name}.</p>`:''}${b.district!==undefined?`<p>Build in ${esc(pack.regions[b.district].name)}.</p>`:''}</section>`;}).join('')}</div></article>`).join('')}<details><summary>Production order and shortages</summary><p>Grain, timber, iron and wool run first; then flour and cloth; then bread, tools, garments and furniture. Within a type, districts and tiles run in order. Staff shortages skip a shift; input shortages reduce its output while wages still apply. Garment shops use cloth before furniture works: pause a tailor or increase cloth capacity when upholstery needs more. Each good has its own warehouse limit; excess is lost after production and before retail.</p></details><p>All recipes and outputs are authored assumptions. Use the learning notes for source-backed concepts.</p>${button('Plan a district','view','data-view="region"')}</section>`;}

 function strategy(){return `<div class="e-strategy"><section><h2>People and finance</h2><label for="e-wage">Wage per worker, per month</label><select id="e-wage" data-policy="wage" ${disabled(locked())}>${[1,2,3].map(n=>`<option value="${n}" ${state.wage===n?'selected':''}>${n} · ${n===1?'output −1':n===3?'output +1':'standard output'}</option>`).join('')}</select><p>Only staffed shifts pay wages. Input shortages still incur wages; paused shifts do not. Buildings always incur upkeep.</p>${pack.preset==='regional'?`<label for="e-tax">Household tax per resident</label><select id="e-tax" data-policy="tax" ${disabled(locked())}>${[0,1,2].map(n=>`<option ${state.tax===n?'selected':''}>${n}</option>`).join('')}</select><p>Each tax level reduces demand by two units per product. This is a game assumption.</p>`:''}<label for="e-services">Monthly public services budget</label><select id="e-services" data-policy="services" ${disabled(locked())}>${[0,4,8].map(n=>`<option value="${n}" ${state.services===n?'selected':''}>${n} cash · ${n/2} services and +${n/4} nature</option>`).join('')}</select><h3>The lending desk</h3><p>Outstanding principal: ${state.debt}. Monthly interest: ${Math.ceil(state.debt*.03)}. Borrowing is financing, not sales. Goal cash is measured after debt.</p><div class="e-controls">${button('Borrow 100','loan',disabled(locked()||state.debt>=300))}${[50,100].map(n=>button('Repay '+n,'repay',`data-amount="${n}" ${disabled(locked()||state.debt<n||state.funds<n)}`)).join('')}</div></section><section><h2>Research for tomorrow</h2>${Object.entries(TECHNOLOGIES).map(([id,t])=>`<article class="e-research"><h3>${t.name}</h3><p>${t.description}</p><p>${t.cost} cash · ${t.months} months</p>${state.tech.includes(id)?'<strong>Completed</strong>':state.research?.id===id?`<strong>${state.research.remaining} months remaining</strong>`:button('Begin research','research',`data-tech="${id}" ${disabled(locked()||!!state.research||state.funds<t.cost)}`)}</article>`).join('')}</section></div>`;}
 function ledger(){return `<section class="e-ledger"><h2>The campaign ledger</h2><p>Starting cash: 300. Closing cash = previous cash + between-month movements + monthly operating balance. This is a cash model; it does not calculate accounting profit.</p><div class="e-table-wrap"><table><caption>Monthly operations</caption><thead><tr>${['Month','Sales','Tax','Wages','Upkeep','Inputs','Interest','Services',...(expanded?['Quality']:[]),'Balance','Cash','Debt'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${state.history.map(h=>`<tr>${['month','sales','taxes','wages','upkeep','materials','interest','services',...(expanded?['qualityCosts']:[]),'net','funds','debt'].map(k=>`<td>${h[k]}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${expanded?12:11}">Advance a month to record operations.</td></tr>`}</tbody></table></div><h3>Cash movements between months</h3><div class="e-table-wrap"><table><thead><tr><th>After month</th><th>Decision</th><th>Change</th><th>Cash</th></tr></thead><tbody>${state.transactions.map(t=>`<tr><td>${t.month}</td><th>${esc(t.description)}</th><td>${signed(t.change)}</td><td>${t.funds}</td></tr>`).join('')||'<tr><td colspan="4">No transactions yet.</td></tr>'}</tbody></table></div><h3>Council record</h3>${state.decisions.map(d=>`<article><h4>${esc(pack.events[d.event].title)}</h4><p>${esc(pack.events[d.event].choices[d.choice].label)}</p><p>${esc(pack.events[d.event].choices[d.choice].explanation)}</p>${button('Review evidence','event-evidence',`data-event="${d.event}"`)}</article>`).join('')}<p>Contracts fulfilled ${state.contracts.length}; deadlines missed ${state.failedContracts.length}. No contract result measures subject mastery.</p></section>`;}
 function learn(){return `<section class="e-learning"><h2>The ideas behind your decisions</h2><p>${esc(pack.hook)}</p>${pack.concepts.map((c,i)=>`<article><h3>${esc(c.title)}</h3><p>${esc(c.explanation)}</p>${button('Read supporting passages','concept',`data-concept="${i}"`)}</article>`).join('')}<h3>${esc(pack.debrief.question)}</h3><p>${esc(pack.debrief.explanation)}</p>${button('Debrief sources','debrief')}<p class="e-muted">${esc(pack.ending)}</p></section>`;}
 function ending(){return `<section class="e-ending"><h2 id="e-ending-title" tabindex="-1">${state.status==='complete'?'A region with a future':state.status==='insolvent'?'The treasury ran out':'The campaign in review'}</h2><p>${esc(pack.ending)}</p>${goals()}<h3>${esc(pack.debrief.question)}</h3><p>${esc(pack.debrief.explanation)}</p><div class="e-controls">${button('Review the ledger','view','data-view="ledger"')}${button('Read debrief evidence','debrief')}${button('Start another campaign','restart')}${button('Games','exit')}</div></section>`;}
 function render(){if(destroyed)return;const token=focusToken(root),f=forecastEconomy(state);root.innerHTML=`<div class="e-game"><header class="e-header"><div><a href="/modes.html" data-e-link="exit">Game library</a><h1>${esc(pack.title)}</h1><p>${esc(pack.subtitle)}</p></div><nav aria-label="Campaign controls">${button('Games','exit')}${button('Rules & sources','rules')}${button('Create a campaign','library')}</nav></header><div class="e-resources" role="group" aria-label="Campaign resources">${[['Month',state.month+' / '+ECONOMY_MONTHS],['Cash',state.funds],['Debt',state.debt],['Residents',f.people],['Nature',state.nature],['Services',f.care]].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}<div class="e-turn">${button(ended()?'Campaign ended':pendingCouncil(state)>=0?'Council decision needed':'Advance month '+(state.month+1),'advance',disabled(locked()),'e-primary')}</div></div><nav class="e-tabs" aria-label="Campaign views">${[['region','Your region'],['market','Markets & contracts'],['strategy','People & research'],...(expanded?[['competition','The competition'],['industries','Industries']]:[]),['ledger','Ledger'],['learning','Learning notes']].map(([k,n])=>button(n,'view',`data-view="${k}" aria-current="${view===k?'page':'false'}"`,view===k?'selected':'')).join('')}</nav><p class="e-notice">${esc(notice||'Your first production line is ready. Inspect the forecast, reserve goods for contracts, or advance a month.')}</p>${recoveryRaw?button('Download recovery copy','recovery','','e-recovery'):''}${council()}${ended()?ending():''}${view==='region'?`<div class="e-region-layout"><main><nav class="e-regions" aria-label="Districts">${REGIONS.map((r,i)=>button(`${esc(pack.regions[i].name)}<small>${state.boards[i]?'Connected':`Opens month ${r.opens}`}</small>`,'region',`data-region="${i}" aria-pressed="${region===i}"`,region===i?'selected':'')).join('')}</nav><div class="e-map-caption"><span>${esc(pack.regions[region].description)}</span><strong>${tool==='inspect'?'Inspect the district':'Place '+FACILITIES[tool].name}</strong></div>${map(f)}${state.boards[region]?buildPalette():''}${contracts()}</main><aside>${forecast(f)}${state.boards[region]?inspector(f):''}<section class="e-targets"><h2>${PRESETS[pack.preset].name} goals</h2><p>Meet these at the end of month 24.</p>${goals()}</section></aside></div>`:view==='market'?company(f):view==='strategy'?strategy():view==='competition'?competition():view==='industries'?industries():view==='ledger'?ledger():learn()}<footer class="e-footer"><span>Original campaign · fictional economic rules</span>${button('Restart campaign','restart','','e-subtle')}</footer><div class="e-modal-host"></div></div>`;modalHTML();restoreFocus(root,token);}
 function commit(action){try{const oldMonth=state.month;state=actEconomy(pack,state,action);notice=action.type==='advance'?`Month ${state.month}: operating balance ${signed(state.history.at(-1).net)}, cash ${state.funds}, nature ${state.nature}.`:state.transactions.at(-1)?.description||'Plan updated.';if(saveBlocked){notice+=' Saving is paused to preserve the unreadable original.';}else{try{storage.setItem(economySaveKey(pack),JSON.stringify(encodeEconomy(pack,state)));}catch{notice+=' Device saving is unavailable. Keep this page open.';}onProgress({pack,record:encodeEconomy(pack,state),kind:'classic'});}render();announcer.say(notice);if(ended()||pendingCouncil(state)>=0){const h=root.querySelector(ended()?'#e-ending-title':'#e-council-title');h?.focus();}else if(state.month!==oldMonth){root.querySelector('[data-e="advance"]')?.focus({preventScroll:true});}}catch(e){notice=e.message;render();announcer.say(notice);}}
 function chooseTile(index){selected=index;if(tool==='inspect'){render();root.querySelector(`[data-e-tile="${index}"]`)?.focus({preventScroll:true});return;}const problem=placementIssue(state,tool,region,index);if(problem){notice=problem;render();announcer.say(problem);}else commit({type:'build',kind:tool,region,index});}
 const click=e=>{const tile=e.target.closest('[data-e-tile]');if(tile){chooseTile(Number(tile.dataset.eTile));return;}const link=e.target.closest('[data-e-link]');if(link){e.preventDefault();onExit();return;}const b=e.target.closest('button[data-e]');if(!b||b.disabled)return;if(!modal)previousFocus=focusToken(root,b);const d=b.dataset;switch(d.e){case 'exit':onExit();break;case 'library':onLibrary();break;case 'view':view=d.view;render();root.querySelector(`[data-view="${view}"]`)?.focus({preventScroll:true});break;case 'region':region=Number(d.region);tool='inspect';render();break;case 'tool':tool=d.kind;notice=tool==='inspect'?'Select a building to inspect it.':`Select an empty tile for ${FACILITIES[tool].name}. Construction costs ${FACILITIES[tool].cost}.`;render();announcer.say(notice);break;case 'choose-tile':chooseTile(Number(root.querySelector('#e-tile-choice').value));break;case 'advance':commit({type:'advance'});break;case 'expand':commit({type:'expand',region:Number(d.region)});break;case 'remove':commit({type:'remove',region,index:selected});break;case 'operate':commit({type:'operate',region,index:selected,enabled:!state.boards[region][selected].enabled});break;case 'quality':commit({type:'quality',good:d.good});break;case 'selling':commit({type:'selling',good:d.good,enabled:!state.selling[d.good]});break;case 'trade':commit({type:'trade',good:d.good,side:d.side,quantity:1});break;case 'marketing':commit({type:'marketing'});break;case 'loan':commit({type:'loan',amount:100});break;case 'repay':commit({type:'repay',amount:Number(d.amount)});break;case 'research':commit({type:'research',tech:d.tech});break;case 'contract':commit({type:'contract',id:Number(d.id)});break;case 'decision':commit({type:'decision',choice:Number(d.choice)});break;case 'concept':{const c=pack.concepts[Number(d.concept)];open(c.title,`<p>${esc(c.explanation)}</p>${sources(c.sourceRefs)}`);break;}case 'event-evidence':{const ev=pack.events[Number(d.event)];open(ev.title,ev.choices.map(c=>`<h3>${esc(c.label)}</h3><p>${esc(c.explanation)}</p>${sources(c.sourceRefs)}`).join(''));break;}case 'debrief':open('Explain the trade-off',`<p>${esc(pack.debrief.question)}</p>${sources(pack.debrief.sourceRefs)}`);break;case 'rules':open('How this economy works',`<p>${esc(economyRulesSummary(pack))}</p><h3>Production order</h3><p>Raw materials are produced first, then intermediate goods and finished products. Connected enabled buildings are staffed in district/tile order, in the order shown in ${expanded?'Industries':'the production recipes'}. Missing workers prevent a shift. Missing inputs reduce its output but still cost wages. Unconnected and paused buildings still incur upkeep.</p><h3>Stock and cash</h3><p>Every raw unit costs one cash. Storage capacity applies separately to each good, after production and before retail. Surplus is lost. Retail demand and market capacity both limit sales. Each market sells at most eight bread and three tools${expanded?', five garments and three furniture items':''}. Export sales use the separate trading quay. Contract goods must already be in stock. Loan principal and repayments appear between months, separately from operating results.</p><h3>Campaign ending</h3><p>A negative end-of-month cash balance ends the run. Month 24 compares all goals; a shortfall opens a review rather than claiming mastery. ${expanded?'Five':'Three'} research projects, public services, wage bands and council choices are fictional levers. Save histories are validated against this exact content version.</p><h3>Your goals</h3>${goals()}<h3>Reviewed sources</h3>${sources(pack.sources.map(s=>s.id))}`);break;case 'restart':open('Start a fresh campaign?',`<p>This replaces the saved run for this campaign. Other towns and campaigns stay separate.</p>${button('Start fresh','restart-confirm','','e-primary')}`);break;case 'restart-confirm':modal=null;state=newEconomy(pack);region=0;view='region';tool='inspect';notice='A new campaign is ready.';if(saveBlocked){notice+=' Saving is paused to preserve the unreadable original.';}else{try{storage.setItem(economySaveKey(pack),JSON.stringify(encodeEconomy(pack,state)));}catch{notice+=' Device saving is unavailable. Keep this page open.';}onProgress({pack,record:encodeEconomy(pack,state),kind:'classic'});}render();root.querySelector('h1').tabIndex=-1;root.querySelector('h1').focus();break;case 'recovery':{const url=URL.createObjectURL(new Blob([recoveryRaw],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=pack.id+'-recovery.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}case 'close':close();break;}};
 const change=e=>{if(e.target.dataset.price)commit({type:'price',good:e.target.dataset.price,value:Number(e.target.value)});if(e.target.dataset.policy)commit({type:'policy',policy:e.target.dataset.policy,value:Number(e.target.value)});};
 const key=e=>{if(modal){if(e.key==='Escape'){e.preventDefault();close();}else access.key(e,root.querySelector('.e-dialog'));return;}const tile=e.target.closest?.('[data-e-tile]');if(!tile)return;const i=Number(tile.dataset.eTile),x=i%6,y=Math.floor(i/6),pos={ArrowLeft:[x-1,y],ArrowRight:[x+1,y],ArrowUp:[x,y-1],ArrowDown:[x,y+1]}[e.key];if(pos){e.preventDefault();if(pos.every(n=>n>=0&&n<6)){selected=pos[1]*6+pos[0];render();root.querySelector(`[data-e-tile="${selected}"]`)?.focus({preventScroll:true});}}else if(['Enter',' '].includes(e.key)){e.preventDefault();chooseTile(i);}};
 root.addEventListener('click',click);root.addEventListener('change',change);root.addEventListener('keydown',key);render();return {destroy(){destroyed=true;access.destroy();announcer.destroy();root.removeEventListener('click',click);root.removeEventListener('change',change);root.removeEventListener('keydown',key);}};
}
