import {withLearningMap} from '../learning-map.js';
import {COUNCIL_RULES,PRESETS,economyCatalog} from './economy-engine.js';
const str=maxLength=>({type:'string',minLength:1,maxLength});
const id={...str(80),pattern:'^[a-z][a-z0-9-]*$'};
const object=properties=>({type:'object',properties,required:Object.keys(properties),additionalProperties:false});
const array=(items,n,maxItems=n)=>({type:'array',items,minItems:n,maxItems});
const refs=array(id,1,12);
export const ECONOMY_ENDING='Use your monthly ledger and the reviewed evidence to explain a decision, its consequences and one limitation of this fictional economy. A successful campaign is not a measure of subject mastery.';
export const ECONOMY_SCHEMA=object({schemaVersion:{type:'integer',enum:[1]},rulesVersion:{type:'integer',enum:[2]},template:{type:'string',enum:['economy-v1']},id,topicId:id,revision:{type:'integer',minimum:1,maximum:100000},title:str(100),subtitle:str(100),hook:str(900),preset:{type:'string',enum:['enterprise','regional']},regions:array(object({name:str(50),description:str(350),sourceRefs:refs}),3),concepts:array(object({title:str(80),explanation:str(600),sourceRefs:refs}),4),events:array(object({title:str(80),prompt:str(450),choices:array(object({label:str(65),explanation:str(550),sourceRefs:refs}),2)}),6),debrief:object({question:str(300),explanation:str(650),sourceRefs:refs})});
export const ECONOMY_PROMPT=`Create economy-v1 with rulesVersion 2, an authored 24-month economic strategy game. Two deterministic competing companies pay for production, adapt next-month prices from public sales and invest in capacity or quality from their own funds. Finite customers allocate purchases among all three suppliers according to price, quality and promotion, constrained by stock and shop capacity. Quality improvements cost cash and incur a per-unit finishing charge. Ten goods support four retail sectors: grain to flour to bread; timber and iron to tools; wool to cloth to garments; timber and cloth to upholstered furniture. Textile and furniture research unlock their facilities. A diversification goal needs at least four units manufactured in three retail sectors during the campaign. No share price, takeover, diplomacy, arbitrary industry or new map. The UI displays all coefficients. The new fair choice boosts market appeal for three months, not guaranteed sales. Choose preset enterprise (trading company) or regional (development council). Use only evidence that fits business, economic trade-offs or historical industrial development; refuse unsuitable material. The model supplies source-backed narrative ONLY. Keep concept explanations below 500 characters and the debrief question below 240 characters. Complete every sentence within its field limit; never cut off a word or sentence to fit. Fixed map: three 6x6 districts, Rivergate initially open, Ironwood opens after month4 for110, Port Meridian after month10 for140; district labels may change but must remain a riverside town, iron/timber district, and trading port. Fixed goods grain/flour/bread, timber/iron/tools, wool/cloth/garments and furniture; do not rename them or claim these simulate a specific historical economy faithfully. Roads connect facilities, residents staff shifts. Players control price, wage, public services, stock reservations, trade, loans, research and contracts. All prices, rival responses, demand curves, game goals, nature/service scores and shock timings are fictional authored coefficients, never factual forecasts. Do not include numerical effects, thresholds or formulas in narrative; UI supplies exact rules. Supply four cited concept notes about (1) cash and costs, (2) production and capacity, (3) trade/technology, (4) people/environment, using only ideas the sources actually support. Six events, exactly two choices each, ordered and semantically matched: month3 invest in trading fair versus retain cash; month7 safeguards versus delay; month11 staff education versus retain cash; month15 repairs versus defer; month19 trading fair versus retain cash; month23 community fund versus retain cash. Each option needs a source-backed explanation separating evidence from fiction; there is no correct-answer grading. Relevant history should include affected people and limitations, never imply inevitable progress. Supply a debrief using actual player ledger values and source evidence. SourceRefs required on every region, concept, decision and debrief. No source text, arbitrary URLs, asset IDs, code, economics rules, goal numbers or ending prose. LearningMap activities council-0 through council-5.`;
export function validateEconomyContent(raw){
 const need=(v,m)=>{if(!v)throw Error(m)},safe=v=>typeof v==='string'&&/^[a-z][a-z0-9-]{0,79}$/.test(v),text=(v,n,label,trim=true)=>{need(typeof v==='string'&&v.trim().length&&v.length<=n,`Invalid ${label}.`);return trim?v.trim():v;};
 need(raw&&raw.schemaVersion===1&&raw.template==='economy-v1'&&safe(raw.id)&&safe(raw.topicId)&&Number.isInteger(raw.revision)&&raw.revision>=1&&raw.revision<=100000,'Invalid economic campaign identity.');
 need(raw.rulesVersion===undefined||raw.rulesVersion===2,'Unknown economic rules version.');
 need(Object.hasOwn(PRESETS,raw.preset),'Choose an authored campaign preset.');
 need(raw.rules===undefined&&raw.geometry===undefined,'Campaign rules and geometry are authored, not editable topic content.');
 need(Array.isArray(raw.sources)&&raw.sources.length>0&&raw.sources.length<=12,'A campaign needs reviewed evidence.');
 const sources=raw.sources.map(s=>{need(s&&safe(s.id),'Invalid source identity.');return {id:s.id,title:text(s.title,160,'source title',false),locator:text(s.locator,240,'source locator',false),excerpt:text(s.excerpt,3000,'source excerpt',false)};});
 const ids=new Set(sources.map(s=>s.id));need(ids.size===sources.length,'Duplicate source identity.');const sourceRefs=r=>{need(Array.isArray(r)&&r.length>0&&r.length<=12&&r.every(k=>ids.has(k)),'Every campaign learning note needs valid source references.');return [...new Set(r)];};
 const collection=(v,n,label)=>{need(Array.isArray(v)&&v.length===n,`Provide exactly ${n} ${label}.`);return v;};
 const regions=collection(raw.regions,3,'regions').map(r=>({name:text(r?.name,50,'region name'),description:text(r.description,350,'region description'),sourceRefs:sourceRefs(r.sourceRefs)}));
 const concepts=collection(raw.concepts,4,'concept notes').map(c=>({title:text(c?.title,80,'concept title'),explanation:text(c.explanation,600,'concept explanation'),sourceRefs:sourceRefs(c.sourceRefs)}));
 const events=collection(raw.events,6,'council meetings').map(e=>{const choices=collection(e?.choices,2,'choices').map(c=>({label:text(c?.label,65,'choice label'),explanation:text(c.explanation,550,'choice explanation'),sourceRefs:sourceRefs(c.sourceRefs)}));need(choices[0].label.toLowerCase()!==choices[1].label.toLowerCase(),'Council choices must be distinct.');return {title:text(e.title,80,'event title'),prompt:text(e.prompt,450,'event prompt'),choices};});
 need(raw.debrief,'Provide a campaign debrief.');const clean={schemaVersion:1,template:'economy-v1',id:raw.id,topicId:raw.topicId,revision:raw.revision,title:text(raw.title,100,'title'),subtitle:text(raw.subtitle,100,'subtitle'),hook:text(raw.hook,900,'opening'),preset:raw.preset,regions,concepts,events,debrief:{question:text(raw.debrief.question,300,'debrief question'),explanation:text(raw.debrief.explanation,650,'debrief explanation'),sourceRefs:sourceRefs(raw.debrief.sourceRefs)},ending:ECONOMY_ENDING,sources};
 need(new TextEncoder().encode(JSON.stringify(clean)).length<=70000,'Campaign content must fit within 70 KB.');if(raw.rulesVersion===2)clean.rulesVersion=2;return withLearningMap(raw,clean);
}
export function economyRulesSummary(pack){if(pack?.rulesVersion===2)return `Twenty-four months, three districts, ten goods and four retail sectors. Bread: grain → flour → bread; tools: timber + iron → tools; garments: wool → cloth → garments; furniture: timber + cloth → furniture. Two funded rivals respond to public sales by changing next-month prices and investing in capacity or quality. Customers are shared between suppliers, bounded by supply and shop capacity. Quality upgrades cost 35 then 70, and each retail unit sold incurs its quality level in finishing cost. Promotion improves market appeal, never guarantees a sale. Five research projects, six mixed-industry contracts, fixed company/regional goals and at least four units manufactured in three retail sectors. Loans cost 3% monthly interest; principal is financing. Council choices: ${economyCatalog(pack).councilRules.map((e,i)=>`${i+1}: ${e.map(c=>c.label).join(' OR ')}`).join('; ')}. Every coefficient is fictional. Historical content must distinguish source facts from this authored market.`;return `Twenty-four months; three connected districts; grain → flour → bread and timber + iron → tools. Prices alter demand against a scripted rival. Wage bands change output and staffing costs. Loans have 3% monthly interest; principal is separate from income. Trade has a bid/ask spread and monthly capacity. Research takes time. Six contracts have deadlines. Six council meetings: ${COUNCIL_RULES.map((e,i)=>`${i+1}: ${e.map(c=>c.label).join(' OR ')}`).join('; ')}. Company and regional goals are fixed by the engine. All numerical values are fictional teaching assumptions.`;}
